mapper.select:
WITH stats AS (
SELECT
CASE
WHEN turnover_days > 360 THEN 'over360'
WHEN turnover_days BETWEEN 270 AND 360 THEN 'd270_360'
WHEN turnover_days BETWEEN 210 AND 270 THEN 'd210_270'
WHEN turnover_days BETWEEN 150 AND 210 THEN 'd150_210'
WHEN turnover_days BETWEEN 120 AND 150 THEN 'd120_150'
WHEN turnover_days BETWEEN 60 AND 120 THEN 'd60_120'
ELSE 'under60'
END as turnover_range,
COUNT(*) as skuCount,
SUM(total_inventory_value) as inventoryValue,
SUM(CAST(NULLIF(sales_amount, '') AS DECIMAL(10,2))) as revenue,
SUM(CAST(NULLIF(gross_profit, '') AS DECIMAL(10,2))) as profit
FROM amz_data_analysis_turnover_mskulist

    and store_name like concat('%', #{storeName}, '%')
    and msku like concat('%', #{msku}, '%')
    and category_level_1 like concat('%',
        #{categoryLevelOne}, '%')

    and category_level_2 like concat('%',
        #{categoryLevelTwo}, '%')

    and fnsku = #{fnsku}
    and local_sku = #{localSku}
    and main_sku = #{mainSku}
    and product_name like concat('%', #{productName},
        '%')

    and asin = #{asin}
    and stock_status = #{stockStatus}

        and sales_7_days between #{params.beginSales7Days} and #{params.endSales7Days}


        and sales_14_days between #{params.beginSales14Days} and #{params.endSales14Days}


        and sales_30_days between #{params.beginSales30Days} and #{params.endSales30Days}


        and sales_90_days between #{params.beginSales90Days} and #{params.endSales90Days}


        and avg_daily_sales between #{params.beginAvgDailySales} and #{params.endAvgDailySales}

    and procurement_in_transit = #{procurementInTransit}

        and local_inventory between #{params.beginLocalInventory} and #{params.endLocalInventory}


        and available between #{params.beginAvailable} and #{params.endAvailable}


        and awaiting_stock between #{params.beginAwaitingStock} and #{params.endAwaitingStock}

    and sku = #{sku}
    and warehouse_name like concat('%',
        #{warehouseName}, '%')

    and stock_warning_days = #{stockWarningDays}
    and
        am_seasonal_product_offseason = #{amSeasonalProductOffseason}

    and
        am_seasonal_product_peak_increase_ratio = #{amSeasonalProductPeakIncreaseRatio}

    and am_seasonal_product_peak =
        #{amSeasonalProductPeak}

    and am_competitor_sales =
        #{amCompetitorSales}

    and am_market_capacity =
        #{amMarketCapacity}

    and
        am_product_lifecycle_status = #{amProductLifecycleStatus}

    and
        am_seasonal_product_offseason_decline = #{amSeasonalProductOffseasonDecline}

    and supplier_name like concat('%', #{supplierName},
        '%')

    and latest_purchase_price = #{latestPurchasePrice}
    and weight = #{weight}
    and volume_cm3 = #{volumeCm3}
    and min_purchase_quantity = #{minPurchaseQuantity}
    and amz_inventory_shelf_time =
        #{amzInventoryShelfTime}

    and reshaper = #{reshaper}
    and reshaping = #{reshaping}
    and in_transit = #{inTransit}
    and available_days = #{availableDays}
    and procurement_days = #{procurementDays}
    and remarks = #{remarks}
    and reserved = #{reserved}
    and planned_stock_in = #{plannedStockIn}
    and sales_person = #{salesPerson}
    and developer = #{developer}
    and listing_date = #{listingDate}
    and is_delete = #{isDelete}
    and created_at = #{createdAt}
    and version = #{version}
    and is_delete = 0
    and DATE(created_at) = CURDATE()

GROUP BY turnover_range
),
totals AS (
SELECT
COUNT(*) as total_count,
SUM(total_inventory_value) as total_value,
SUM(CAST(NULLIF(sales_amount, '') AS DECIMAL(10,2))) as total_revenue,
SUM(CAST(NULLIF(gross_profit, '') AS DECIMAL(10,2))) as total_profit
FROM amz_data_analysis_turnover_mskulist

    and store_name like concat('%', #{storeName}, '%')

    and is_delete = 0
    and DATE(created_at) = CURDATE()

)
SELECT
s.turnover_range,
s.skuCount,
s.skuCount / t.total_count * 100 as skuRatio,
s.inventoryValue,
s.inventoryValue / t.total_value * 100 as inventoryRatio,
s.revenue,
CASE WHEN t.total_revenue > 0 THEN s.revenue / t.total_revenue * 100 ELSE 0 END as revenueRatio,
s.profit,
CASE WHEN t.total_profit > 0 THEN s.profit / t.total_profit * 100 ELSE 0 END as profitRatio,
CASE WHEN s.revenue > 0 THEN s.profit / s.revenue * 100 ELSE 0 END as profitMargin
FROM stats s, totals t
ORDER BY
CASE s.turnover_range
WHEN 'over360' THEN 1
WHEN 'd270_360' THEN 2
WHEN 'd210_270' THEN 3
WHEN 'd150_210' THEN 4
WHEN 'd120_150' THEN 5
WHEN 'd60_120' THEN 6
ELSE 7
END

